"""Run the original full-event queue after its verified kernel completed.

Only the simulation array budget changes from 12288 to 14336 MiB. The original
queue suffix, numerical sources, complete horizon and all comparison gates are
retained. Previous attempts and outputs remain untouched.
"""
import ast
import copy
import hashlib
import importlib.metadata
import json
import os
import platform
import subprocess
from pathlib import Path
from datetime import datetime,timezone

ROOT=Path('/Users/b09501028/Downloads/bem2d.jl/Tatva-BEM')
OLD=ROOT/'bem/outputs/resumed-radau-fine-study-20261028'
SOURCE=ROOT/'bem/outputs/resumed-radau-fine-study-20261028.py'
OUT=ROOT/'bem/outputs/resumed-radau-event-study-20261103'
KERNEL=Path('/Volumes/Gauss-T7/Tatva-BEM-cache/fresh-radau2us-graded-q12-full45-20261028')
AUDIT=Path('/Volumes/Gauss-T7/Tatva-BEM-cache/complete-radau-original-causal-audit-20261103')
PYTHON='/opt/homebrew/Caskroom/miniconda/base/envs/tatva/bin/python'

def sha(path):
 h=hashlib.sha256()
 with Path(path).open('rb')as f:
  for b in iter(lambda:f.read(4*1024**2),b''):h.update(b)
 return h.hexdigest()
def read(path):return json.loads(Path(path).read_text())
def write(path,data):Path(path).write_text(json.dumps(data,indent=2,allow_nan=False)+'\n')

if OUT.exists() or AUDIT.exists():raise RuntimeError('Require new owned event/audit directories')
old=read(OLD/'status.json')
if not(old['phase']=='attention_required' and old['stages'][0]['exit_code']==0
       and old['stages'][0]['name']=='resume_complete_radau_kernel'
       and old['stages'][1]['exit_code']==1):raise RuntimeError('Old queue state changed; inspect before starting')
if 'Estimated stage solver arrays need 13294.0 MiB' not in (OLD/'complete_event_segments64-128.log').read_text():
 raise RuntimeError('Require the preserved pre-numerical resource rejection')
for pid in [57967,97341,97343,old['numerical_child_pid']]:
 r=subprocess.run(['ps','-p',str(pid),'-o','lstart=,command='],capture_output=True,text=True)
 if r.stdout.strip():raise RuntimeError('An old PID exists; inspect identity before starting any work')
frozen=read(OLD/'frozen_inputs.json')
changed=[p for p,v in frozen.items()if sha(p)!=v]
if changed:raise RuntimeError('Original numerical/protected inputs changed: '+repr(changed))
kernel=read(KERNEL/'summary.json');journal=read(KERNEL/'sampling-journal.json')
if (kernel['status']!='completed_compact_radau_resolvent_kernel_only' or journal['phase']!='completed'
    or kernel['full_steps']!=22500 or kernel['dt_s']!=2e-6 or kernel['correction_steps']!=22500):
 raise RuntimeError('Full original kernel/horizon is not complete')
for name in ['numpy','scipy']:
 if kernel['environment'][name]!=importlib.metadata.version(name):raise RuntimeError('Cached runtime changed: '+name)
verified_jax_context=ROOT/'bem/outputs/trace-policy-coarse-kernel-20261101-v1/jax-backend-context.json'
verified_jax=read(verified_jax_context)['runtime']
for name in ['jax','jaxlib']:
 if importlib.metadata.version(name)!=verified_jax[name]:raise RuntimeError('Verified simulation AD runtime changed: '+name)
if kernel['environment']['platform']!=platform.platform():raise RuntimeError('Cached host platform changed')
if subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip()!='6a06ecc0634b75c8f2b99215503270b71614c970':
 raise RuntimeError('Require the verified numerical-source commit')
if subprocess.run(['git','diff','--quiet','--','bem/tools','bem/src'],cwd=ROOT).returncode:
 raise RuntimeError('Numerical worktree changed')

tree=ast.parse(SOURCE.read_text())
boundary=next(i for i,n in enumerate(tree.body)if isinstance(n,ast.Expr) and ast.unparse(n)=='os.chdir(ROOT)')
tries=[n for n in tree.body[boundary:]if isinstance(n,ast.Try)]
if len(tries)!=1:raise RuntimeError('Original queue boundary changed')
original=tries[0]
start=next(i for i,n in enumerate(original.body)if isinstance(n,ast.Assign) and ast.unparse(n)=='runs = []')
tail=copy.deepcopy(original);tail.body=tail.body[start:]
changes=0
for node in ast.walk(tail):
 if isinstance(node,ast.Call)and isinstance(node.func,ast.Name)and node.func.id=='execute'and len(node.args)>1:
  if isinstance(node.args[1],ast.Constant)and node.args[1].value=='simulate_compact_radau.py':
   for i,value in enumerate(node.args[:-1]):
    if isinstance(value,ast.Constant)and value.value=='--max-memory-mb':
     if not isinstance(node.args[i+1],ast.Constant)or node.args[i+1].value!=12288:
      raise RuntimeError('Original simulation budget changed')
     node.args[i+1]=ast.Constant(value=14336);changes+=1
if changes!=1:raise RuntimeError('Expected exactly the shared event-loop resource argument')
namespace={'__name__':'original_queue_helpers','__file__':str(Path(__file__).resolve())}
exec(compile(ast.Module(body=tree.body[:boundary],type_ignores=[]),str(SOURCE)+'|helpers','exec'),namespace)
OUT.mkdir()
os.chdir(ROOT)
namespace.update(STUDY=OUT,AUDIT=AUDIT,frozen=frozen.copy())
for path in [Path(__file__).resolve(),OLD/'status.json',SOURCE,KERNEL/'summary.json',verified_jax_context,ROOT/'bem/outputs/resume-complete-radau-events-20261103-v1-failure.json']:
 namespace['frozen'][str(path)]=sha(path)
write(OUT/'frozen_inputs.json',namespace['frozen'])
write(OUT/'inherited_costs.json',dict(previous_queue=old,previous_costs=read(OLD/'inherited_costs.json'),
 kernel_completed_without_rebuild=True,previous_resource_rejection_retained=True,
 all_prior_paid_work_and_pauses_retained=True,goal_achieved=False))
write(OUT/'recovery_manifest.json',dict(utc=datetime.now(timezone.utc).isoformat(),pid=os.getpid(),
 source_queue=str(SOURCE),source_queue_sha256=sha(SOURCE),old_status_sha256=sha(OLD/'status.json'),
 kernel_summary_sha256=sha(KERNEL/'summary.json'),only_command_change=dict(
  tool='simulate_compact_radau.py',max_memory_mb_before=12288,max_memory_mb_after=14336),
 cpu_budget_cores=3.85,hard_memory_rss_cap=False,physical_horizon_seconds=.045,steps=22500,
 full_horizon_and_all_acceptance_gates_unchanged=True,
 numerical_suffix_ast_sha256=hashlib.sha256(ast.dump(tail,include_attributes=False).encode()).hexdigest()))
namespace['status']('verified_complete_kernel_starting_original_events',kernel_completed_without_rebuild=True)
exec(compile(ast.fix_missing_locations(ast.Module(body=[tail],type_ignores=[])),str(SOURCE)+'|events-recovery','exec'),namespace)
